def build_with_diagonals():
    output = [[0]*30 for _ in range(24)]

    v_sep_cols = [0, 7, 14, 21, 28]
    h_sep_rows = [2, 7, 12, 17, 22]

    # Start with separators
    for c in v_sep_cols:
        for r in range(24):
            if r not in h_sep_rows:
                output[r][c] = 9

    for r in h_sep_rows:
        for c in range(30):
            output[r][c] = 9

    # Background in regions
    for r in range(24):
        for c in range(30):
            if r not in h_sep_rows and c not in v_sep_cols:
                output[r][c] = 5

    # Add diagonals in each region!
    # Region bounded by (r_min, c_min) to (r_max, c_max) exclusive of sep rows/cols
    for ri, hr in enumerate(h_sep_rows[:-1]):
        for ci, vc in enumerate(v_sep_cols[:-1]):
            r_start = hr + 1
            r_end = h_sep_rows[ri+1]
            c_start = vc + 1
            c_end = v_sep_cols[ci+1]

            # Main diagonal
            for dr in range(r_start, r_end):
                for dc in range(c_start, c_end):
                    if (dc - c_start) == (dr - r_start):
                        output[dr][dc] = 9

                    # Anti-diagonal
                    if (dc - c_start) + (dr - r_start) == r_end - r_start - 1:
                        output[dr][dc] = 9

            # Primary diagonal through center
            mid_r = (r_start + r_end - 1) // 2
            mid_c = (c_start + c_end - 1) // 2
            for k in range(-(min(mid_r-r_start, mid_c-c_start), min(r_end-mid_r-1, c_end-mid_c-1))):
                rr, cc = mid_r+k, mid_c-k
                if r_start <= rr < r_end and c_start <= cc < c_end:
                    output[rr][cc] = 9

    return output

