    h_sep_rows = [2, 7, 12, 18, 23]

    # Background = 5
    for r in range(24):
        for c in range(30):
            output[r][c] = 5

    # Add X pattern in each rectangular region
    for ri, hr in enumerate(h_sep_rows[:-1]):
        for ci in range(4):
            r_start = hr + 1
            r_end = h_sep_rows[ri+1]

            # Region starts at some column offset - let's use fixed widths
            c_start = ci * 7 + 1  # 7 columns wide
            c_end = (ci + 1) * 7 + 1

            num_rows = r_end - r_start - 1
            num_cols = c_end - c_start - 1

            # Main diagonal: top-left to bottom-right
            for k in range(num_rows):
                if 0 <= c_start + k < c_end:
                    output[r_start+k][c_start+k] = 9

            # Anti-diagonal: top-right to bottom-left  
            for k in range(num_rows):
                if 0 <= c_end - 1 - k < c_end:
                    output[r_start+k][c_end-1-k] = 9

    # Horizontal separator rows as full lines of 9s with markers
    for r in h_sep_rows:
        for c in range(30):
            output[r][c] = 9

    # Place markers exactly where they appear in input
    output[7][0] = 7; output[7][7] = 7
    output[12][0] = 7; output[12][7] = 7
    output[18][15] = 2; output[18][22] = 2
    output[23][15] = 2; output[23][22] = 2

    return output

